p\"},\"mediaText\":\"(max-width: 768px)\",\"atRuleType\":\"media\"},{\"selectors\":[{\"name\":\"gjs-cell\",\"private\":1}],\"style\":{\"min-height\":\"75px\",\"flex-grow\":\"1\",\"flex-basis\":\"100%\"}},{\"selectors\":[\"#iksv\"],\"style\":{\"padding\":\"10px\"}},{\"selectors\":[\"#iick\"],\"style\":{\"color\":\"rgb(60, 67, 74)\",\"font-family\":\"monospace\",\"font-size\":\"12px\",\"background-color\":\"rgb(240, 240, 241)\"}}],\"pages\":[{\"frames\":[{\"component\":{\"type\":\"wrapper\",\"stylable\":[\"background\",\"background-color\",\"background-image\",\"background-repeat\",\"background-attachment\",\"background-position\",\"background-size\"],\"components\":[{\"name\":\"Row\",\"droppable\":\".gjs-cell\",\"resizable\":{\"tl\":0,\"tc\":0,\"tr\":0,\"cl\":0,\"cr\":0,\"bl\":0,\"br\":0,\"minDim\":1},\"classes\":[{\"name\":\"gjs-row\",\"private\":1}],\"attributes\":{\"id\":\"ik6w\"},\"components\":[{\"name\":\"Cell\",\"draggable\":\".gjs-row\",\"stylable-require\":[\"flex-basis\"],\"unstylable\":[\"width\"],\"resizable\":{\"tl\":0,\"tc\":0,\"tr\":0,\"cl\":0,\"cr\":1,\"bl\":0,\"br\":0,\"minDim\":1,\"bc\":0,\"currentUnit\":1,\"step\":0.2,\"keyWidth\":\"flex-basis\"},\"classes\":[{\"name\":\"gjs-cell\",\"private\":1}],\"components\":[{\"type\":\"text\",\"attributes\":{\"id\":\"iksv\"},\"components\":[{\"tagName\":\"span\",\"type\":\"text\",\"attributes\":{\"id\":\"iick\"},\"components\":[{\"type\":\"textnode\",\"content\":\"[snippet id=\\\"neve-clone\\\"]\"}]}]}]}]}]}}],\"type\":\"main\",\"id\":\"ZJeQGalWM4G1BPSl\"}]},\"pages\":[{\"html\":\"<body><div class=\\\"gjs-row\\\" id=\\\"ik6w\\\"><div class=\\\"gjs-cell\\\"><div id=\\\"iksv\\\"><span id=\\\"iick\\\">[snippet id=\\\"neve-clone\\\"]</span></div></div></div></body>\",\"css\":\"* { box-sizing: border-box; } body {margin: 0;}.gjs-row{display:flex;justify-content:flex-start;align-items:stretch;flex-wrap:nowrap;padding-top:10px;padding-right:10px;padding-bottom:10px;padding-left:10px;}.gjs-cell{min-height:75px;flex-g